import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('register', () => {
    it('throws synchronously naming the tool when a static inputSchema fails compilation', () => {
      const registry = new ToolRegistry();

      expect(() =>
        registry.register(
          {
            name: 'broken_tool',
            description: 'Tool with an uncompilable JSON Schema',
            inputSchema: {
              type: 'object',
              properties: {count: {type: 'not-a-type'}},
            },
          },
          async () => 'unreachable'
        )
      ).toThrow(/broken_tool/);
    });
  });
});

